"""Presentation labels; stored job action IDs remain stable."""
NAMES = {'lastfm_refresh': 'Refresh Last.fm Discovery', 'artwork_sync': 'Update Album Artwork', 'request_status': 'Refresh Request Status', 'musicbrainz_lookup': 'Find Albums with MusicBrainz', 'prepare_views': 'Prepare Page Data', 'file_audit': 'Scan Local Files', 'file_audit_duplicates': 'Verify Duplicate Files', 'library_metadata': 'Refresh Artist Metadata', 'library_metadata_all': 'Refresh Library Metadata', 'artist_metadata': 'Refresh Artist Metadata', 'local_catalog': 'Refresh MusicBrainz Catalog', 'local_scan': 'Scan Local Files', 'text_playlist': 'Add Text Playlist', 'recreate': 'Recreate Plex Playlist', 'plex_scan': 'Scan Plex Library', 'lidarr_scan': 'Scan Lidarr Library', 'lidarr_webhook': 'Process Lidarr Event', 'album_finalize': 'Finalize Imported Album', 'release_change': 'Change Album Release', 'reconcile': 'Reconcile Availability', 'retry_missing': 'Retry Missing Matches', 'playlist_settings': 'Update Playlist Settings', 'availability': 'Check Media Availability', 'ignore_batch': 'Ignore tracks', 'match_batch': 'Apply Match Queue', 'lidarr_add': 'Request Album', 'lidarr_search': 'Retry Lidarr Search', 'playlist_description': 'Update Playlist Description', 'sync': 'Sync', 'health': 'Health Check', 'analyze': 'Analyze playlist', 'add': 'Add playlist', 'fix_match': 'Fix Match', 'track_match': 'Update track matches', 'remove': 'Remove playlists', 'backup': 'Backup', 'check_updates': 'Check for Updates', 'restore_backup': 'Restore Backup', 'database_optimize': 'Optimize Database', 'database_compact': 'Compact Database', 'database_cleanup': 'Clean Database History', 'database_rebuild': 'Rebuild Derived Data', 'ignore': 'Ignore track', 'startup': 'Startup', 'jobs': 'Jobs'}

def action_name(value):
    import re
    return NAMES.get(value) or (value.replace("_", " ").replace("-", " ").title() if re.fullmatch(r"[a-zA-Z0-9_-]+", value) and ("_" in value or "-" in value) else value)
